INSERT INTO `permissions` (`name`, `area`, `description`, `purpose`, `added_by`) VALUES ('users.view', 'Users', 'See the list of Content Studio users, with their email addresses, names, roles, and status.', 'For people who need to know who has access to Content Studio, such as team leads and support. It shows email addresses, so give it only to people who need them.', 'FR-00004');--> statement-breakpoint
INSERT INTO `permissions` (`name`, `area`, `description`, `purpose`, `added_by`) VALUES ('users.manage', 'Users', 'Create users, change their names, email addresses, and roles, deactivate and reactivate them, and check that the Access group matches the users.', 'For the people responsible for Content Studio access. It controls who can sign in and what they can do, so give it to as few people as possible.', 'FR-00004');--> statement-breakpoint
INSERT INTO `permissions` (`name`, `area`, `description`, `purpose`, `added_by`) VALUES ('roles.view', 'Roles', 'See the roles, the permissions each role has, and the permission list with descriptions and purposes.', 'For people who need to understand what each role allows before asking for access or reviewing it.', 'FR-00004');--> statement-breakpoint
INSERT INTO `permissions` (`name`, `area`, `description`, `purpose`, `added_by`) VALUES ('roles.manage', 'Roles', 'Create, change, and delete roles, and choose which permissions each role has.', 'For the people responsible for Content Studio access. Changing a role changes what every user with that role can do, so give it to as few people as possible.', 'FR-00004');
